def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate a repeated line in the color key. Its nonzero colors give the
    # sequence used to recolor copies of the main shape.
    candidates = []

    for r in range(h):
        sig = tuple((c, grid[r][c]) for c in range(w) if grid[r][c] != 0)
        if len(sig) < 2:
            continue
        end = r + 1
        while end < h:
            other = tuple((c, grid[end][c]) for c in range(w)
                          if grid[end][c] != 0)
            if other != sig:
                break
            end += 1
        if end - r >= 2:
            candidates.append((end - r, len(sig), [v for c, v in sig]))

    for c in range(w):
        sig = tuple((r, grid[r][c]) for r in range(h) if grid[r][c] != 0)
        if len(sig) < 2:
            continue
        end = c + 1
        while end < w:
            other = tuple((r, grid[r][end]) for r in range(h)
                          if grid[r][end] != 0)
            if other != sig:
                break
            end += 1
        if end - c >= 2:
            candidates.append((end - c, len(sig), [v for r, v in sig]))

    if not candidates:
        return [row[:] for row in grid]

    _, _, palette = max(candidates, key=lambda x: (x[0], x[1]))

    # Find the largest connected component in a palette color. Diagonal
    # adjacency is part of the shape.
    seen = set()
    components = []
    colors = set(palette)
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in colors or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = rr + dr, cc + dc
                        if (0 <= nr < h and 0 <= nc < w and
                                grid[nr][nc] == color and
                                (nr, nc) not in seen):
                            seen.add((nr, nc))
                            stack.append((nr, nc))
            components.append((len(comp), color, comp))

    if not components:
        return [row[:] for row in grid]

    _, anchor_color, shape = max(components, key=lambda x: x[0])
    top = min(r for r, c in shape)
    left = min(c for r, c in shape)
    shape_h = max(r for r, c in shape) - top + 1
    offsets = [(r - top, c - left) for r, c in shape]

    # The existing shape color marks its position in the palette sequence.
    index = palette.index(anchor_color)
    start = top - index * shape_h

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(palette):
        copy_top = start + i * shape_h
        for dr, dc in offsets:
            rr, cc = copy_top + dr, left + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
